-- Design draft; not executed by the current SQLite runtime.
BEGIN;
CREATE TABLE users(id text PRIMARY KEY,name text UNIQUE NOT NULL,status text NOT NULL CHECK(status IN('active','disabled')),created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE plans(id text PRIMARY KEY,name text UNIQUE NOT NULL,enabled boolean NOT NULL,allowed_modes jsonb NOT NULL,allowed_models jsonb NOT NULL,max_duration_seconds integer NOT NULL,allowed_resolutions jsonb NOT NULL,daily_limit_points numeric NOT NULL,monthly_limit_points numeric NOT NULL,max_concurrency integer NOT NULL,max_queued_requests integer NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE projects(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),plan_id text NOT NULL REFERENCES plans(id),name text NOT NULL,status text NOT NULL CHECK(status IN('active','disabled')),created_at bigint NOT NULL,updated_at bigint NOT NULL,UNIQUE(user_id,name));
CREATE TABLE jobs(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),project_id text NOT NULL REFERENCES projects(id),api_key_id text,account_id text NOT NULL,kind text NOT NULL CHECK(kind IN('image','video')),source_type text NOT NULL,model text NOT NULL,request_fingerprint text NOT NULL,idempotency_key_hash text,status text NOT NULL,result_json jsonb,quoted_points numeric NOT NULL DEFAULT 0,quote_known boolean NOT NULL,upstream_task_id text,unknown_hold_until bigint,processing_deadline_at bigint,reconcile_after bigint,uncertainty_reason text,archive_status text NOT NULL DEFAULT 'none',archive_attempts integer NOT NULL DEFAULT 0,archive_retry_at bigint,archive_error text,created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE UNIQUE INDEX jobs_idempotency_unique ON jobs(api_key_id,idempotency_key_hash) WHERE idempotency_key_hash IS NOT NULL;
CREATE TABLE budget_entries(job_id text PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,account_id text NOT NULL,quoted_points numeric NOT NULL,state text NOT NULL CHECK(state IN('reserved','charged','released')),day_window_start bigint NOT NULL,month_window_start bigint NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE usage_ledger(id text PRIMARY KEY,job_id text NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,user_id text NOT NULL,project_id text NOT NULL,api_key_id text,account_id text NOT NULL,entry_type text NOT NULL,points numeric NOT NULL,reason text NOT NULL,created_at bigint NOT NULL,UNIQUE(job_id,entry_type,reason));
CREATE TABLE provider_submissions(id text PRIMARY KEY,job_id text NOT NULL UNIQUE REFERENCES jobs(id) ON DELETE CASCADE,account_id text NOT NULL,request_fingerprint text NOT NULL,upstream_fingerprint text NOT NULL,catalog_revision text NOT NULL,baseline_json jsonb NOT NULL,outcome text NOT NULL,ambiguity_reason text,created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE provider_correlations(id text PRIMARY KEY,submission_id text NOT NULL UNIQUE REFERENCES provider_submissions(id),job_id text NOT NULL UNIQUE REFERENCES jobs(id),provider text NOT NULL,account_id text NOT NULL,upstream_task_id text,upstream_asset_id text,creation_code text,evidence_type text NOT NULL,confidence text NOT NULL,correlated_at bigint NOT NULL);
CREATE UNIQUE INDEX provider_task_unique ON provider_correlations(provider,account_id,upstream_task_id) WHERE upstream_task_id IS NOT NULL;
CREATE TABLE job_worker_leases(job_id text PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,worker_id text NOT NULL,lease_token text NOT NULL UNIQUE,fencing_token bigint NOT NULL,lease_expires_at bigint NOT NULL,heartbeat_at bigint NOT NULL,acquired_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE webhook_outbox(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),job_id text NOT NULL REFERENCES jobs(id),event_type text NOT NULL,payload_json jsonb NOT NULL,status text NOT NULL,attempts integer NOT NULL,next_attempt_at bigint NOT NULL,last_error text,delivered_at bigint,created_at bigint NOT NULL,updated_at bigint NOT NULL,UNIQUE(job_id,event_type));
ALTER TABLE jobs ADD COLUMN recovery_claim_token text;
ALTER TABLE jobs ADD COLUMN recovery_claimed_by text;
ALTER TABLE jobs ADD COLUMN recovery_claim_expires_at bigint;
CREATE INDEX worker_claim_idx ON jobs(status,updated_at);
CREATE INDEX recovery_claim_idx ON jobs(recovery_claim_expires_at,updated_at);
CREATE INDEX webhook_due_idx ON webhook_outbox(status,next_attempt_at);
COMMIT;
